<script setup lang="ts">
/**
 * Monitor2 — V52 ZScore Simplified Dashboard
 * Shows only: transport bar, trade summary, BTC chart, entry conditions panel.
 * Data from bot_controller /signals endpoint (same as StrategyMonitorView).
 */
import { use } from 'echarts/core';
import { LineChart, CandlestickChart } from 'echarts/charts';
import { GridComponent, TooltipComponent, LegendComponent, MarkLineComponent, MarkAreaComponent, DataZoomComponent } from 'echarts/components';
import { CanvasRenderer } from 'echarts/renderers';
import VChart from 'vue-echarts';

import TransportBar from '@/components/monitor/TransportBar.vue';
import TradeSummary from '@/components/monitor/TradeSummary.vue';
import { buildBtcChart, buildEquityChart } from '@/components/monitor/chartBuilders';
import type { PairRawData } from '@/components/monitor/types';
import { PAIRS, GROUP_A, GROUP_B, GROUP_A_ACTIVE, GROUP_B_ACTIVE, PAIR_COLORS, coin } from '@/components/monitor/types';

use([CanvasRenderer, LineChart, CandlestickChart, GridComponent, TooltipComponent, LegendComponent, MarkLineComponent, MarkAreaComponent, DataZoomComponent]);

const CTRL = `${window.location.protocol}//${window.location.hostname}:8084`;

// ── State ──
const saved = JSON.parse(localStorage.getItem('monitor2Ctrl') || '{}');
const browseStart = ref(saved.start || '2026-04-01');
const browseEnd = ref(saved.end || '2026-05-01');
const frameIndex = ref(0);
const lastRendered = ref(-1);
const totalFrames = ref(0);
const currentTimestamp = ref('');
const playing = ref(false);
const playInterval = ref<number | null>(null);
const playSpeed = ref(saved.speed || 500);
const loading = ref(false);
const visibleCandles = ref(saved.visible || 100);

// ── Data stores ──
const rawData = reactive<Record<string, PairRawData>>({});
const equityRaw = reactive<{ equity: number[]; initial: number }>({ equity: [], initial: 100 });
const chartLabels = reactive<Record<string, string[]>>({});
const chartOhlc = reactive<Record<string, number[][]>>({});
const chartEquity = reactive<number[]>([]);

function saveLocal() {
  localStorage.setItem('monitor2Ctrl', JSON.stringify({
    start: browseStart.value, end: browseEnd.value,
    speed: playSpeed.value, visible: visibleCandles.value,
  }));
}

function sliceTail<T>(arr: T[]): T[] {
  const n = visibleCandles.value;
  if (n <= 0 || n >= 99999 || arr.length <= n) return arr;
  return arr.slice(arr.length - n);
}

// ── Strategy name + timeframe ──
const strategyName = ref('V53 Warmup');
const strategyTimeframe = ref('5m');

// ── Dynamic groups from backend ──
const dynGroupA = ref<string[]>([]);
const dynGroupB = ref<string[]>([]);

// ── Server-side summary (authoritative, no frontend calculation) ──
const serverSummary = reactive({
  total_trades: 0, wins: 0, losses: 0, win_pct: 0,
  total_profit_abs: 0, profit_pct: 0, final_balance: 100, initial_balance: 100,
});

// ── Data loading ──
async function loadAllData() {
  loading.value = true;
  saveLocal();
  totalFrames.value = 0;
  // Clear all previous data
  for (const pair of Object.keys(rawData)) {
    delete rawData[pair];
  }
  for (const pair of Object.keys(chartLabels)) {
    chartLabels[pair] = [];
    chartOhlc[pair] = [];
  }
  equityRaw.equity = [];
  equityRaw.initial = 100;
  chartEquity.length = 0;
  try {
    const resp = await fetch(`${CTRL}/bt-signals?start=${browseStart.value}&end=${browseEnd.value}&timeframe=5m`);
    const data = await resp.json();
    // Load ALL pairs from backend response (not hardcoded PAIRS)
    for (const key of Object.keys(data)) {
      if (key.startsWith('_')) continue;
      rawData[key] = data[key];
      if (!totalFrames.value) totalFrames.value = data[key].labels.length;
      chartLabels[key] = [];
      chartOhlc[key] = [];
    }
    if (data._equity) {
      equityRaw.equity = data._equity.equity;
      equityRaw.initial = data._equity.initial;
    }
    if (data._summary) {
      Object.assign(serverSummary, data._summary);
    }
    if (data._meta) {
      if (data._meta.bot_name) strategyName.value = data._meta.bot_name;
      else if (data._meta.strategy) strategyName.value = data._meta.strategy;
      if (data._meta.timeframe) strategyTimeframe.value = data._meta.timeframe;
      if (data._meta.group_a) dynGroupA.value = data._meta.group_a;
      if (data._meta.group_b) dynGroupB.value = data._meta.group_b;
    }
    chartEquity.length = 0;
  } catch { /* */ }
  frameIndex.value = 0;
  lastRendered.value = -1;
  syncToFrame();
  loading.value = false;

  // Debug load
  console.log('[Monitor2] RAW KEYS:', Object.keys(rawData));
  console.log('[Monitor2] dynGroupA:', dynGroupA.value);
  console.log('[Monitor2] dynGroupB:', dynGroupB.value);
  const loadedPairs = Object.keys(rawData).filter(p => !p.startsWith('_'));
  let dbgCount = 0;
  for (const pair of loadedPairs) {
    const r = rawData[pair];
    if (!r?.trade_ranges) continue;
    for (const tr of r.trade_ranges) {
      if (tr.exit_index <= 0) dbgCount++;
    }
  }
  console.log(`[Monitor2] Loaded: ${totalFrames.value} frames, ${loadedPairs.length} pairs: ${loadedPairs.join(', ')}`);
  console.log(`[Monitor2] Trades at frame 0: ${dbgCount}. Total trades: ${serverSummary.total_trades}`);
  // Check z-scores
  for (const pair of loadedPairs) {
    const r = rawData[pair];
    if (!r) continue;
    const pzSample = r.pair_zscore?.[100] ?? 'MISSING';
    const szSample = r.spread_zscore?.[100] ?? 'MISSING';
    const volSample = r.vol_ok?.[100] ?? 'MISSING';
    console.log(`[Monitor2] ${pair}: pz[100]=${pzSample}, sz[100]=${szSample}, vol[100]=${volSample}, labels=${r.labels?.length}`);
  }
}

// ── Frame sync ──
function syncToFrame() {
  const target = frameIndex.value;
  const syncPairs = Object.keys(rawData).filter(p => !p.startsWith('_'));
  if (target > lastRendered.value) {
    for (let i = lastRendered.value + 1; i <= target; i++) {
      for (const pair of syncPairs) {
        const r = rawData[pair];
        if (!r || i >= r.labels.length) continue;
        if (!chartLabels[pair]) chartLabels[pair] = [];
        if (!chartOhlc[pair]) chartOhlc[pair] = [];
        chartLabels[pair].push(r.labels[i]);
        chartOhlc[pair].push(r.ohlc[i]);
      }
      chartEquity.push(equityRaw.equity[i] ?? equityRaw.initial);
    }
  } else if (target < lastRendered.value) {
    for (const pair of syncPairs) {
      if (chartLabels[pair]) chartLabels[pair].length = target + 1;
      if (chartOhlc[pair]) chartOhlc[pair].length = target + 1;
    }
    chartEquity.length = target + 1;
  }
  lastRendered.value = target;
  // Get timestamp from first pair that has labels
  for (const pair of syncPairs) {
    const r = rawData[pair];
    if (r && target < r.labels.length) { currentTimestamp.value = r.labels[target]; break; }
  }
}

// ── Transport ──
function stepFrame(d: number) {
  frameIndex.value = Math.max(0, Math.min(frameIndex.value + d, totalFrames.value - 1));
  syncToFrame();
}
function seekFrame(i: number) {
  frameIndex.value = Math.max(0, Math.min(i, totalFrames.value - 1));
  syncToFrame();
}
function togglePlay() {
  if (playing.value) {
    if (playInterval.value) clearInterval(playInterval.value);
    playInterval.value = null;
    playing.value = false;
  } else {
    playing.value = true;
    playInterval.value = window.setInterval(() => {
      if (frameIndex.value >= totalFrames.value - 1) { togglePlay(); return; }
      stepFrame(1);
    }, playSpeed.value);
  }
}
function updateSpeed(s: number) { playSpeed.value = s; saveLocal(); }

// ── BTC chart ──
const btcChart = computed(() =>
  buildBtcChart(
    sliceTail(chartLabels['BTC/USDC:USDC'] || []),
    sliceTail(chartOhlc['BTC/USDC:USDC'] || []),
  ),
);

// ── Z-Score Charts (one per group) ──
const expandZChart = ref(true);

function buildGroupZChart(groupPairs: string[], groupColor: string, groupName: string) {
  const fi = frameIndex.value;
  if (!groupPairs.length) return null;
  const raw0 = rawData[groupPairs[0]];
  if (!raw0?.labels?.length) return null;

  // Use all data up to current frame (or all if at end)
  const endIdx = Math.min(fi + 1, raw0.labels.length);
  if (endIdx <= 1) return null;
  const windowSize = visibleCandles.value || 100;
  const startIdx = Math.max(0, endIdx - windowSize);
  const labels = raw0.labels.slice(startIdx, endIdx);
  // V53: use per-group spread (spread_z_a or spread_z_b). Fallback to spread_zscore (V52).
  const spreadCol = groupName === 'A' ? 'spread_z_a' : groupName === 'B' ? 'spread_z_b' : 'spread_zscore';
  const spreadData = (raw0[spreadCol] || raw0.spread_zscore || []).slice(startIdx, endIdx);

  if (fi % 200 === 0) {
    console.log(`[ZChart ${groupName}] fi=${fi}, startIdx=${startIdx}, endIdx=${endIdx}, labels=${labels.length}, spread_sample=${spreadData[Math.floor(spreadData.length/2)]}, pairs=${groupPairs.join(',')}`);
  }

  const pairColors = ['#4caf50', '#81c784', '#a5d6a7', '#c8e6c9'];
  const bColors = ['#b388ff', '#7c4dff', '#9575cd', '#d1c4e9'];
  const colorSet = groupName === 'A' ? pairColors : bColors;

  const pairSeries = groupPairs.map((pair, i) => {
    const r = rawData[pair];
    if (!r?.pair_zscore) return null;
    return {
      name: pair.split('/')[0],
      type: 'line',
      data: r.pair_zscore.slice(startIdx, endIdx),
      lineStyle: { width: 1.5 },
      itemStyle: { color: colorSet[i % colorSet.length] },
      symbol: 'none',
      z: 2,
    };
  }).filter(Boolean);

  return {
    animation: false,
    grid: { top: 30, right: 50, bottom: 25, left: 45 },
    tooltip: { trigger: 'axis', backgroundColor: '#161b22', borderColor: '#30363d', textStyle: { color: '#e0e0e0', fontFamily: 'monospace', fontSize: 11 } },
    legend: {
      data: ['Spread', ...groupPairs.map(p => p.split('/')[0])],
      textStyle: { color: '#666', fontFamily: 'monospace', fontSize: 10 },
      top: 0,
    },
    xAxis: {
      type: 'category',
      data: labels,
      axisLabel: { color: '#484f58', fontSize: 9, fontFamily: 'monospace', interval: Math.floor(labels.length / 5) },
      axisLine: { lineStyle: { color: '#21262d' } },
      splitLine: { show: false },
    },
    yAxis: {
      type: 'value',
      axisLabel: { color: '#484f58', fontSize: 9, fontFamily: 'monospace' },
      axisLine: { lineStyle: { color: '#21262d' } },
      splitLine: { lineStyle: { color: '#21262d' } },
    },
    series: [
      // Entry threshold lines
      {
        name: 'Entry',
        type: 'line',
        data: labels.map(() => -2.1),
        lineStyle: { width: 1, type: 'dashed', color: '#4caf50', opacity: 0.4 },
        symbol: 'none', z: 0,
        markArea: { silent: true, itemStyle: { color: 'rgba(76,175,80,0.04)' }, data: [[{ yAxis: -2.1 }, { yAxis: -10 }]] },
      },
      {
        name: 'Entry+',
        type: 'line',
        data: labels.map(() => 2.1),
        lineStyle: { width: 1, type: 'dashed', color: '#f85149', opacity: 0.4 },
        symbol: 'none', z: 0,
        markArea: { silent: true, itemStyle: { color: 'rgba(248,81,73,0.04)' }, data: [[{ yAxis: 2.1 }, { yAxis: 10 }]] },
      },
      // Pair Z entry threshold
      {
        name: 'pz±1.2',
        type: 'line',
        data: labels.map(() => -1.2),
        lineStyle: { width: 1, type: 'dotted', color: '#666', opacity: 0.3 },
        symbol: 'none', z: 0,
      },
      {
        name: 'pz±1.2+',
        type: 'line',
        data: labels.map(() => 1.2),
        lineStyle: { width: 1, type: 'dotted', color: '#666', opacity: 0.3 },
        symbol: 'none', z: 0,
      },
      // Zero
      {
        name: 'Zero',
        type: 'line',
        data: labels.map(() => 0),
        lineStyle: { width: 1, type: 'dotted', color: '#30363d' },
        symbol: 'none', z: 0,
      },
      // Spread Z (yellow, shared)
      {
        name: 'Spread',
        type: 'line',
        data: spreadData,
        lineStyle: { width: 2, color: '#ffd54f' },
        itemStyle: { color: '#ffd54f' },
        symbol: 'none', z: 3,
        areaStyle: {
          color: { type: 'linear', x: 0, y: 0, x2: 0, y2: 1,
            colorStops: [{ offset: 0, color: 'rgba(255,213,79,0.1)' }, { offset: 0.5, color: 'rgba(255,213,79,0)' }, { offset: 1, color: 'rgba(255,213,79,0.1)' }],
          },
        },
      },
      // Per-pair Z lines
      ...pairSeries,
    ],
  };
}

const zChartAPairs = computed(() => {
  const pairs = Object.keys(rawData).filter(p => !p.startsWith('_') && !p.startsWith('BTC'));
  if (dynGroupA.value.length) return pairs.filter(p => dynGroupA.value.includes(p));
  return pairs.slice(0, Math.ceil(pairs.length / 2));
});
const zChartBPairs = computed(() => {
  const pairs = Object.keys(rawData).filter(p => !p.startsWith('_'));
  if (dynGroupB.value.length) return pairs.filter(p => dynGroupB.value.includes(p));
  return pairs.slice(Math.ceil(pairs.length / 2));
});
const zChartA = computed(() => buildGroupZChart(zChartAPairs.value, '#4caf50', 'A'));
const zChartB = computed(() => buildGroupZChart(zChartBPairs.value, '#b388ff', 'B'));

// ── Current frame data ──
const btcCandle = computed(() => {
  const raw = rawData['BTC/USDC:USDC'];
  if (!raw || frameIndex.value >= raw.ohlc.length) return null;
  const o = raw.ohlc[frameIndex.value];
  return { close: raw.price[frameIndex.value], pair_z: raw.pair_zscore?.[frameIndex.value] ?? 0, spread_z: raw.spread_zscore?.[frameIndex.value] ?? 0 };
});

// ── Entry Conditions PER PAIR ──
interface PairCondition {
  name: string;
  ok: boolean;
  value: string;
  detail: string;
  pct: number; // 0-100 proximity to threshold (100 = ready)
}
interface PairEntry {
  pair: string;
  coinName: string;
  group: 'A' | 'B';
  color: string;
  conditions: PairCondition[];
  score: number;
  total: number;
  possibleTag: string;
  isActive: boolean; // true = trades, false = z-score calc only
}

// Heatmap color: red(0%) → yellow(50%) → green(100%)
function heatColor(pct: number): string {
  const p = Math.max(0, Math.min(100, pct));
  if (p >= 100) return '#4caf50';
  if (p >= 75) {
    const t = (p - 75) / 25;
    const r = Math.round(255 * (1 - t) + 76 * t);
    const g = Math.round(213 * (1 - t) + 175 * t);
    return `rgb(${r},${g},50)`;
  }
  if (p >= 50) {
    const t = (p - 50) / 25;
    const r = Math.round(255);
    const g = Math.round(152 + (213 - 152) * t);
    return `rgb(${r},${g},50)`;
  }
  if (p >= 25) {
    const t = (p - 25) / 25;
    const r = Math.round(248);
    const g = Math.round(81 + (152 - 81) * t);
    return `rgb(${r},${g},50)`;
  }
  const t = p / 25;
  return `rgb(248,${Math.round(81 * t)},${Math.round(73 * (1 - t) + 50 * t)})`;
}

// Heatmap background: same color but very dim
function heatBg(pct: number): string {
  const c = heatColor(pct);
  return c.replace('rgb(', 'rgba(').replace(')', ',0.08)');
}

const pairEntryConditions = computed<PairEntry[]>(() => {
  const fi = frameIndex.value;
  const result: PairEntry[] = [];
  const spreadThreshold = 2.1;
  const pzThreshold = 1.2;

  const tradablePairs = Object.keys(rawData).filter(p => !p.startsWith('_') && !p.startsWith('BTC'));

  for (const pair of tradablePairs) {
    const raw = rawData[pair];
    if (!raw || fi >= raw.labels.length) continue;

    const isA = dynGroupA.value.includes(pair);

    // ALL values from backend (computed by strategy modules)
    const pz = raw.pair_zscore?.[fi] ?? 0;
    const sz = raw.spread_zscore?.[fi] ?? 0;
    const volOk = raw.vol_ok?.[fi] ?? false;
    const regimeOk = (raw.regime_ok?.[fi] ?? 1) === 1;
    const spreadVolOk = (raw.spread_vol_ok?.[fi] ?? 1) === 1;
    const corr = raw.rolling_corr?.[fi] ?? 0;
    const volRatio = raw.vol_ratio?.[fi] ?? 1;
    const btcMom = raw.btc_mom?.[fi] ?? 0;
    const btcAtrZ = raw.btc_atr_z?.[fi] ?? 0;
    const btcPump = raw.btc_pump?.[fi] ?? false;
    const btcDump = raw.btc_dump?.[fi] ?? false;
    const btcHighVol = raw.btc_high_vol?.[fi] ?? false;

    const conditions: PairCondition[] = [];

    // Determine entry direction
    let possibleTag = '';
    if (isA) {
      possibleTag = 'mr_long_a';
    } else {
      possibleTag = sz < -spreadThreshold ? 'mr_short_b' : sz > spreadThreshold ? 'mr_long_b' : 'wait';
    }
    const side = isA ? 'long' : (possibleTag === 'mr_short_b' ? 'short' : 'long');

    // 1. Spread Z
    const spreadOk = isA ? sz < -spreadThreshold : Math.abs(sz) >= spreadThreshold;
    conditions.push({
      name: 'Spread Z', ok: spreadOk, value: `${sz.toFixed(3)}σ`,
      detail: spreadOk ? (isA ? '< -2.1 ✓' : '|sz| > 2.1 ✓') : `falta ${(spreadThreshold - Math.abs(sz)).toFixed(2)}σ`,
      pct: Math.min(100, (Math.abs(sz) / spreadThreshold) * 100),
    });

    // 2. Pair Z
    let pzOk = false;
    if (isA) pzOk = pz < -pzThreshold;
    else if (possibleTag === 'mr_short_b') pzOk = pz > pzThreshold;
    else if (possibleTag === 'mr_long_b') pzOk = pz < -pzThreshold;
    let pzPct = 0;
    if (isA) pzPct = pz < 0 ? Math.min(100, (Math.abs(pz) / pzThreshold) * 100) : 0;
    else if (possibleTag === 'mr_short_b') pzPct = pz > 0 ? Math.min(100, (pz / pzThreshold) * 100) : 0;
    else if (possibleTag === 'mr_long_b') pzPct = pz < 0 ? Math.min(100, (Math.abs(pz) / pzThreshold) * 100) : 0;
    conditions.push({
      name: 'Pair Z', ok: pzOk, value: `${pz.toFixed(3)}σ`,
      detail: pzOk ? 'threshold ✓' : possibleTag === 'wait' ? 'aguardando spread' : `falta ${(pzThreshold - Math.abs(pz)).toFixed(2)}σ`,
      pct: pzPct,
    });

    // 3. Volume (from strategy)
    conditions.push({
      name: 'Volume', ok: volOk, value: `${volRatio.toFixed(1)}x`,
      detail: volOk ? '> threshold ✓' : 'abaixo da média',
      pct: volOk ? 100 : Math.min(99, volRatio * 100),
    });

    // 4. Regime (from strategy — correlation based)
    conditions.push({
      name: 'Regime', ok: regimeOk, value: regimeOk ? 'RANGING' : 'FAIL',
      detail: `corr=${corr.toFixed(2)}`,
      pct: regimeOk ? 100 : 0,
    });

    // 5. Spread Vol (from strategy)
    conditions.push({
      name: 'Spread Vol', ok: spreadVolOk, value: spreadVolOk ? 'OK' : 'ERRATIC',
      detail: spreadVolOk ? 'spread stable ✓' : 'spread too volatile',
      pct: spreadVolOk ? 100 : 0,
    });

    // 6. BTC Safety (from strategy)
    const btcSafe = side === 'long' ? !btcDump && !btcHighVol : !btcPump && !btcHighVol;
    conditions.push({
      name: 'BTC Safe', ok: btcSafe,
      value: btcHighVol ? 'CHAOS' : btcPump ? 'PUMP' : btcDump ? 'DUMP' : 'OK',
      detail: `mom=${btcMom.toFixed(1)}% atr_z=${btcAtrZ.toFixed(1)}`,
      pct: btcSafe ? 100 : 0,
    });

    // 7. Pair Free — no active trade on this pair at this frame
    let pairHasTrade = false;
    if (raw.trade_ranges) {
      for (const tr of raw.trade_ranges) {
        if (fi >= tr.entry_index && fi <= tr.exit_index) { pairHasTrade = true; break; }
      }
    }
    conditions.push({
      name: 'Pair Free', ok: !pairHasTrade,
      value: pairHasTrade ? 'IN TRADE' : 'Free',
      detail: pairHasTrade ? 'already has open position' : 'available for entry',
      pct: pairHasTrade ? 0 : 100,
    });

    // 8. Group Balance — check imbalance between groups
    let countA = 0, countB = 0;
    for (const p of Object.keys(rawData).filter(k => !k.startsWith('_') && !k.startsWith('BTC'))) {
      const r = rawData[p];
      if (!r?.trade_ranges) continue;
      for (const tr of r.trade_ranges) {
        if (fi >= tr.entry_index && fi <= tr.exit_index) {
          if (dynGroupA.value.includes(p)) countA++;
          else countB++;
        }
      }
    }
    const maxImbalance = 2; // from config balance.max_group_imbalance
    const wouldImbalance = isA ? (countA + 1 - countB > maxImbalance) : (countB + 1 - countA > maxImbalance);
    conditions.push({
      name: 'Balance', ok: !wouldImbalance,
      value: `A:${countA} B:${countB}`,
      detail: wouldImbalance ? `imbalance > ${maxImbalance}` : 'balanced ✓',
      pct: wouldImbalance ? 0 : 100,
    });

    // 9. Cooldown — 24h block after catastrophic loss (stop_loss, mkt_stop, no_reversion with big loss)
    const cooldownHours = 24;
    const cooldownCandles = cooldownHours * 60 / 5; // 288 candles for 5m
    let inCooldown = false;
    let cooldownDetail = 'no recent loss';
    // Check ALL pairs for recent losses (cooldown is global)
    for (const p of Object.keys(rawData).filter(k => !k.startsWith('_') && !k.startsWith('BTC'))) {
      const r2 = rawData[p];
      if (!r2?.trade_ranges) continue;
      for (const tr of r2.trade_ranges) {
        if (tr.exit_index < fi && fi - tr.exit_index < cooldownCandles) {
          const exitTag = tr.exit_tag || '';
          if (exitTag === 'stop_loss' || exitTag === 'mkt_stop_dump' || exitTag === 'mkt_stop_pump' || (exitTag === 'no_reversion' && tr.profit_pct < -3)) {
            inCooldown = true;
            const remainCandles = cooldownCandles - (fi - tr.exit_index);
            const remainHours = (remainCandles * 5 / 60).toFixed(1);
            cooldownDetail = `${p.split('/')[0]} ${exitTag} ${tr.profit_pct}% — ${remainHours}h left`;
            break;
          }
        }
      }
      if (inCooldown) break;
    }
    conditions.push({
      name: 'Cooldown', ok: !inCooldown,
      value: inCooldown ? 'ACTIVE' : 'Clear',
      detail: cooldownDetail,
      pct: inCooldown ? 0 : 100,
    });

    const score = conditions.filter(c => c.ok).length;
    const isActive = isA ? GROUP_A_ACTIVE.includes(pair) : GROUP_B_ACTIVE.includes(pair);
    result.push({
      pair, coinName: coin(pair),
      group: isA ? 'A' : 'B',
      color: isA ? '#4caf50' : '#b388ff',
      conditions, score, total: conditions.length,
      possibleTag: score === conditions.length ? possibleTag : 'wait',
      isActive,
    });
  }

  return result;
});

// ── Exit Conditions PER OPEN TRADE ──
interface PairExitCondition {
  name: string;
  ok: boolean;     // true = exit would trigger
  value: string;
  detail: string;
  pct: number;     // 0-100 proximity to exit trigger
}
interface PairExit {
  pair: string;
  coinName: string;
  group: 'A' | 'B';
  color: string;
  side: string;
  tag: string;
  entryPrice: number;
  currentProfit: number;
  duration: number;
  durationFmt: string;
  conditions: PairExitCondition[];
  exitSignal: string; // which exit would fire, or 'HOLD'
}

const pairExitConditions = computed<PairExit[]>(() => {
  const fi = frameIndex.value;
  const result: PairExit[] = [];

  // Exit config thresholds (V53 with Partial Stop)
  const partialStopTrigger = -0.04;
  const stoploss = -0.04; // Partial Stop replaces fixed -7%
  const roiSchedule = [{ min: 0, pct: 0.025 }, { min: 3, pct: 0.015 }, { min: 10, pct: 0.01 }, { min: 20, pct: 0.005 }];
  const trailTrigger = 0.012;
  const trailDistance = 0.006;
  const scalpMinProfit = 0.012;
  const scalpZThreshold = 0.2;
  const timeStopCandles = 72; // 6h in 5m candles

  const exitTradablePairs = Object.keys(rawData).filter(p => !p.startsWith('BTC') && !p.startsWith('_'));

  for (const pair of exitTradablePairs) {
    const raw = rawData[pair];
    if (!raw?.trade_ranges) continue;

    // Find active trade at current frame
    let activeTrade = null;
    for (const tr of raw.trade_ranges) {
      if (fi >= tr.entry_index && fi <= tr.exit_index) { activeTrade = tr; break; }
    }
    if (!activeTrade) continue;

    const isA = dynGroupA.value.includes(pair);
    const isLong = activeTrade.side === 'long';
    const entryPrice = activeTrade.entry_price;
    const currentPrice = raw.price[fi] || entryPrice;
    const profit = isLong
      ? (currentPrice - entryPrice) / entryPrice
      : (entryPrice - currentPrice) / entryPrice;
    const duration = fi - activeTrade.entry_index;
    const durationSec = duration * 5 * 60; // candles × 5m × 60s
    const durationMin = duration * 5;
    const pz = raw.pair_zscore?.[fi] ?? 0;

    // Format duration: seconds → "Xh Ym" or "Xm Ys"
    function fmtDur(totalMin: number): string {
      if (totalMin >= 60) return `${Math.floor(totalMin / 60)}h ${totalMin % 60}m`;
      return `${totalMin}m`;
    }

    const conditions: PairExitCondition[] = [];
    let exitSignal = 'HOLD';

    // 1. ROI — check each level
    let roiTarget = 0.025;
    for (const r of roiSchedule) {
      if (durationMin >= r.min) roiTarget = r.pct;
    }
    const roiOk = profit >= roiTarget;
    const roiPct = Math.min(100, Math.max(0, (profit / roiTarget) * 100));
    if (roiOk && exitSignal === 'HOLD') exitSignal = 'roi';
    conditions.push({
      name: 'ROI',
      ok: roiOk,
      value: `${(profit * 100).toFixed(2)}%`,
      detail: roiOk ? `≥ ${(roiTarget * 100).toFixed(1)}% target ✓` : `target ${(roiTarget * 100).toFixed(1)}% (falta ${((roiTarget - profit) * 100).toFixed(2)}%)`,
      pct: roiPct,
    });

    // 2. Trailing Stop — activates at 1.2%, then trails at 0.6%
    const trailActive = profit >= trailTrigger;
    const trailPct = Math.min(100, Math.max(0, (profit / trailTrigger) * 100));
    conditions.push({
      name: 'Trailing',
      ok: trailActive,
      value: trailActive ? `Ativo ${(trailDistance * 100).toFixed(1)}%` : `${(profit * 100).toFixed(2)}%`,
      detail: trailActive ? `trail ${(trailDistance * 100).toFixed(1)}% abaixo do pico` : `ativa em ${(trailTrigger * 100).toFixed(1)}% (falta ${((trailTrigger - profit) * 100).toFixed(2)}%)`,
      pct: trailPct,
    });

    // 3. Z-Score Scalp — pair_z crosses zero with min profit
    const scalpProfitOk = profit >= scalpMinProfit;
    const scalpZCross = isLong ? pz > scalpZThreshold : pz < -scalpZThreshold;
    const scalpOk = scalpProfitOk && scalpZCross;
    const scalpProfitPct = Math.min(100, Math.max(0, (profit / scalpMinProfit) * 100));
    const scalpZPct = isLong
      ? Math.min(100, Math.max(0, (pz / scalpZThreshold) * 100))
      : Math.min(100, Math.max(0, (-pz / scalpZThreshold) * 100));
    const scalpPct = (scalpProfitPct + scalpZPct) / 2;
    if (scalpOk && exitSignal === 'HOLD') exitSignal = 'zscore_scalp';
    conditions.push({
      name: 'Scalp',
      ok: scalpOk,
      value: `pz=${pz.toFixed(2)}`,
      detail: scalpOk ? 'z reverted + profit OK ✓' : `profit ${scalpProfitOk ? '✓' : `falta ${((scalpMinProfit - profit) * 100).toFixed(2)}%`} | z ${scalpZCross ? '✓' : (isLong ? `< ${scalpZThreshold}` : `> -${scalpZThreshold}`)}`,
      pct: scalpPct,
    });

    // 4. Time Stop — 6h max
    const timePct = Math.min(100, (duration / timeStopCandles) * 100);
    const timeOk = duration >= timeStopCandles;
    if (timeOk && exitSignal === 'HOLD') exitSignal = 'time_stop';
    conditions.push({
      name: 'Time',
      ok: timeOk,
      value: fmtDur(durationMin),
      detail: timeOk ? '≥ 6h → force exit' : `${fmtDur(360 - durationMin)} restantes`,
      pct: timePct,
    });

    // 5. Partial Stop (-4% custom stoploss)
    const psPct = profit <= 0 ? Math.min(100, Math.max(0, (Math.abs(profit) / Math.abs(partialStopTrigger)) * 100)) : 0;
    const psOk = profit <= partialStopTrigger;
    if (psOk && exitSignal === 'HOLD') exitSignal = 'partial_stop';
    conditions.push({
      name: 'P.Stop',
      ok: psOk,
      value: `${(profit * 100).toFixed(2)}%`,
      detail: psOk ? `≤ ${(partialStopTrigger * 100)}% HIT ✗` : profit < 0 ? `${((partialStopTrigger - profit) * 100).toFixed(1)}% até stop` : 'em lucro',
      pct: psPct,
    });

    // 6. No Reversion — pair_z diverging after 6 candles (30min)
    const nrCandles = 6;
    const nrZThreshold = 0.8;
    let nrOk = false;
    let nrPct = 0;
    let nrDetail = '';
    if (duration >= nrCandles) {
      const entryPz = raw.pair_zscore?.[activeTrade.entry_index] ?? 0;
      const currentPzDelta = isLong ? (pz - entryPz) : (entryPz - pz);
      // Negative delta means diverging (going wrong direction)
      nrOk = currentPzDelta < -nrZThreshold && profit < -0.02;
      nrPct = currentPzDelta < 0 ? Math.min(100, (Math.abs(currentPzDelta) / nrZThreshold) * 100) : 0;
      nrDetail = nrOk ? `z diverged ${Math.abs(currentPzDelta).toFixed(2)}σ → EXIT` : `Δz=${currentPzDelta.toFixed(2)}σ (threshold ${nrZThreshold})`;
      if (nrOk && exitSignal === 'HOLD') exitSignal = 'no_reversion';
    } else {
      nrDetail = `checking after ${nrCandles * 5}m (${(nrCandles - duration) * 5}m left)`;
      nrPct = Math.min(100, (duration / nrCandles) * 100);
    }
    conditions.push({
      name: 'No Rev',
      ok: nrOk,
      value: duration >= nrCandles ? `Δz=${((raw.pair_zscore?.[fi] ?? 0) - (raw.pair_zscore?.[activeTrade.entry_index] ?? 0)).toFixed(2)}` : `${duration * 5}m/${nrCandles * 5}m`,
      detail: nrDetail,
      pct: nrPct,
    });

    // 7. Market Stop (BTC chaos/dump/pump)
    conditions.push({
      name: 'Mkt Stop',
      ok: false,
      value: 'OK',
      detail: isLong ? 'sem dump detectado' : 'sem pump detectado',
      pct: 0,
    });

    result.push({
      pair,
      coinName: coin(pair),
      group: isA ? 'A' : 'B',
      color: isA ? '#4caf50' : '#b388ff',
      side: activeTrade.side,
      tag: activeTrade.tag,
      entryPrice,
      currentProfit: profit,
      duration: durationMin,
      durationFmt: fmtDur(durationMin),
      conditions,
      exitSignal,
    });
  }

  return result;
});

// ── Dynamic pairs list (from loaded data, not hardcoded) ──
const dataPairs = computed(() => Object.keys(rawData).filter(p => !p.startsWith('_')));
const dataTradablePairs = computed(() => dataPairs.value.filter(p => !p.startsWith('BTC')));

// ── Trade stats ──
const tradeStats = computed(() => {
  let w = 0, l = 0;
  for (const pair of dataPairs.value) {
    for (const s of rawData[pair]?.signals || []) {
      if (s.type === 'exit' && s.index <= frameIndex.value) { s.win ? w++ : l++; }
    }
  }
  return { w, l, pct: w + l > 0 ? ((w / (w + l)) * 100).toFixed(0) : '0' };
});

const openCount = computed(() => {
  let count = 0;
  for (const pair of dataPairs.value) {
    const raw = rawData[pair];
    if (!raw?.trade_ranges) continue;
    for (const tr of raw.trade_ranges) {
      if (frameIndex.value >= tr.entry_index && frameIndex.value <= tr.exit_index) count++;
    }
  }
  return count;
});

// ── Frame-progressive stats (uses real profit_abs from backend) ──
const frameStats = computed(() => {
  const fi = frameIndex.value;
  let wins = 0, losses = 0, equity = serverSummary.initial_balance;
  for (const pair of dataPairs.value) {
    const raw = rawData[pair];
    if (!raw?.trade_ranges) continue;
    for (const tr of raw.trade_ranges) {
      if (tr.exit_index <= fi) {
        if (tr.profit_abs !== undefined) {
          equity += tr.profit_abs;
        }
        if (tr.win) wins++; else losses++;
      }
    }
  }
  const total = wins + losses;
  const winPct = total > 0 ? (wins / total * 100).toFixed(1) : '0';
  const profitPct = ((equity / serverSummary.initial_balance - 1) * 100).toFixed(1);
  return { wins, losses, equity: Math.round(equity * 100) / 100, winPct, profitPct };
});

const progressPct = computed(() => totalFrames.value > 1 ? (frameIndex.value / (totalFrames.value - 1) * 100).toFixed(1) : '0');

// Find next frame with an active trade (for "jump to" link)
const nextTradeFrame = computed(() => {
  const fi = frameIndex.value;
  let nearest = -1;
  for (const pair of dataPairs.value) {
    const raw = rawData[pair];
    if (!raw?.trade_ranges) continue;
    for (const tr of raw.trade_ranges) {
      if (tr.entry_index > fi) {
        if (nearest < 0 || tr.entry_index < nearest) nearest = tr.entry_index;
        break;
      }
    }
  }
  return nearest;
});

// ── Equity chart ──
const equityLabels = computed(() => {
  for (const pair of PAIRS) {
    if (chartLabels[pair]?.length) return chartLabels[pair];
  }
  return [];
});
const equityChart = computed(() => buildEquityChart(sliceTail(equityLabels.value), sliceTail([...chartEquity]), equityRaw.initial));

// ── Trade History ──
interface TradeHistoryItem {
  pair: string; side: string; tag: string; exit_tag: string;
  entry_label: string; exit_label: string; entry_index: number; exit_index: number;
  entry_price: number; exit_price: number; profit_pct: number; profit_abs: number; win: boolean; duration: number; leverage: number;
}

const tradeHistory = computed<TradeHistoryItem[]>(() => {
  const trades: TradeHistoryItem[] = [];
  for (const pair of dataPairs.value) {
    const raw = rawData[pair];
    if (!raw?.trade_ranges) continue;
    for (const tr of raw.trade_ranges) {
      if (tr.profit_pct !== null && tr.exit_index <= frameIndex.value) {
        trades.push({
          pair, side: tr.side, tag: tr.tag, exit_tag: tr.exit_tag,
          entry_label: raw.labels[tr.entry_index] || '',
          exit_label: raw.labels[tr.exit_index] || '',
          entry_index: tr.entry_index, exit_index: tr.exit_index,
          entry_price: tr.entry_price,
          exit_price: raw.price[tr.exit_index] || 0,
          profit_pct: tr.profit_pct, profit_abs: tr.profit_abs ?? 0, win: tr.win ?? false,
          duration: tr.exit_index - tr.entry_index, leverage: tr.leverage ?? 1,
        });
      }
    }
  }
  trades.sort((a, b) => a.exit_label.localeCompare(b.exit_label));
  return trades;
});

const historyTotals = computed(() => {
  const h = tradeHistory.value;
  const wins = h.filter(t => t.win).length;
  const losses = h.length - wins;
  const totalProfitAbs = h.reduce((s, t) => s + t.profit_abs, 0);
  const totalProfitPct = (totalProfitAbs / serverSummary.initial_balance * 100);
  const avgProfitAbs = h.length > 0 ? totalProfitAbs / h.length : 0;
  const avgDuration = h.length > 0 ? h.reduce((s, t) => s + t.duration, 0) / h.length : 0;
  const best = h.length > 0 ? Math.max(...h.map(t => t.profit_pct)) : 0;
  const worst = h.length > 0 ? Math.min(...h.map(t => t.profit_pct)) : 0;
  return {
    total: h.length, wins, losses,
    totalProfitAbs: totalProfitAbs.toFixed(2),
    totalProfitPct: totalProfitPct.toFixed(2),
    avgProfitAbs: avgProfitAbs.toFixed(2),
    avgDuration: Math.round(avgDuration),
    best: best.toFixed(2), worst: worst.toFixed(2),
  };
});

const expandBtc = ref(true);
const expandEntry = ref(true);
const expandExit = ref(true);
const expandEquity = ref(true);
const expandHistory = ref(true);

onMounted(() => { loadAllData(); });
// ── Detach / Drag ──
const detached = ref(false);
const dragPos = reactive({ x: 100, y: 60 });
const dragging = ref(false);
const dragOffset = reactive({ x: 0, y: 0 });

function toggleDetach() { detached.value = !detached.value; }

function onDragStart(e: MouseEvent) {
  dragging.value = true;
  dragOffset.x = e.clientX - dragPos.x;
  dragOffset.y = e.clientY - dragPos.y;
  document.addEventListener('mousemove', onDragMove);
  document.addEventListener('mouseup', onDragEnd);
}
function onDragMove(e: MouseEvent) {
  if (!dragging.value) return;
  dragPos.x = e.clientX - dragOffset.x;
  dragPos.y = e.clientY - dragOffset.y;
}
function onDragEnd() {
  dragging.value = false;
  document.removeEventListener('mousemove', onDragMove);
  document.removeEventListener('mouseup', onDragEnd);
}

onUnmounted(() => {
  if (playInterval.value) clearInterval(playInterval.value);
  document.removeEventListener('mousemove', onDragMove);
  document.removeEventListener('mouseup', onDragEnd);
});
</script>

